"""Static vector annotation review. No local raster processing or ML."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
src=Path(__file__).parent
data=json.loads((src/'annotations.json').read_text())
out=ROOT/'runs/hemp-manual-segmentation-v1';out.mkdir(exist_ok=True)
page='''<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Astra manual plant segmentation</title><style>
body{margin:0;padding:15px;background:#f3f4ed;color:#18352e;font:16px system-ui}header{display:flex;gap:16px;align-items:center;flex-wrap:wrap}h1{font-size:22px;margin:5px 0}select,button{font:inherit;padding:7px}.pair{display:flex;gap:20px;overflow:auto}.pair>img{height:72vh;width:auto;image-rendering:pixelated}svg{width:100%;max-width:1524px;display:block;background:#0b1007}#note{max-width:1000px}#full{max-width:762px}a{color:#126167}text{pointer-events:none}
</style><header><h1>Astra · manual annotation</h1><label>View <select id="row"><option value="-1">Whole image</option><option value="0">Row 1 · y 0–89</option><option value="1">Row 2 · y 89–178</option><option value="2">Row 3 · y 178–266</option><option value="3">Row 4 · y 266–355</option><option value="4">Row 5 · y 355–444</option></select></label><label><input id="show" type="checkbox" checked> Polygons</label><label><input id="grid" type="checkbox"> Coordinate grid</label><label><input id="pixels" type="checkbox" checked> Original pixels</label><label><input id="instances" type="checkbox"> Instance colors</label></header><p id="note">First manual pass: approximate visible-part outlines, not complete pixel-accurate labels. Pink regions are unresolved review areas, not organ masks. Green: leaflets; gold: stems; gray: supports. Whole view: original left, manual overlay right. Shared coordinates preserve labels across the 5 × 5 grid. <span id="count"></span></p><div class="pair"><img id="originalPreview" src="../hemp-sam3-comparison-v1/results/sam3/reference/input.png" alt="Original image for side-by-side comparison"><svg id="canvas" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 381 444"></svg></div><p><a href="../../research/hemp-defoliation/manual-segmentation-v1/annotations.json">Editable polygon labels (JSON)</a> · <a href="../../research/hemp-defoliation/manual-segmentation-v1/coco-draft.json">COCO-style draft</a> · <a href="labels.svg">Labels only (SVG)</a> · <a href="../../research/hemp-defoliation/manual-segmentation-v1/README.md">Limitations and method</a> · <a href="../hemp-segmentation-roundup-v1/index.html">Previous model experiments</a></p><script>
const data=DATA,ns='http://www.w3.org/2000/svg',canvas=document.querySelector('#canvas');
function el(tag,attrs){let e=document.createElementNS(ns,tag);for(let [k,v] of Object.entries(attrs))e.setAttribute(k,v);return e;}
function render(){let row=Number(document.querySelector('#row').value),y0=row<0?0:Math.max(0,data.grid_rows[row]-10),y1=row<0?444:Math.min(444,data.grid_rows[row+1]+10);canvas.setAttribute('viewBox',`0 ${y0} 381 ${y1-y0}`);document.querySelector('#originalPreview').style.display=row<0?'block':'none';canvas.style.width=row<0?'auto':'100%';canvas.style.height=row<0?'72vh':'auto';canvas.style.maxWidth=row<0?'762px':'1524px';canvas.replaceChildren();if(document.querySelector('#pixels').checked)canvas.append(el('image',{href:'../hemp-sam3-comparison-v1/results/sam3/reference/input.png',x:0,y:0,width:381,height:444,style:'image-rendering:pixelated'}));
if(document.querySelector('#show').checked)for(let p of data.polygons){let color=p.label==='leaflet'?'#31e2a4':p.label==='stem'?'#ffd556':p.label==='support'?'#acb5c5':'#ff7bcd';if(document.querySelector('#instances').checked&&p.label!=='unknown_cluster')color=`hsl(${(Number(p.id.slice(1))*137.5)%360} 75% 65%)`;let poly=el('polygon',{points:p.points.map(q=>q.join(',')).join(' '),fill:color,'fill-opacity':p.label==='unknown_cluster'?'0':document.querySelector('#pixels').checked?'.22':'1',stroke:color,'stroke-width':'.4','stroke-dasharray':p.label==='unknown_cluster'?'1.5 1':''});let title=el('title',{});title.textContent=p.id+' · '+p.label+' · '+p.certainty;poly.append(title);canvas.append(poly);}
if(document.querySelector('#grid').checked){for(let x=0;x<=380;x+=20){canvas.append(el('line',{x1:x,x2:x,y1:y0,y2:y1,stroke:'#ffffff','stroke-opacity':'.1','stroke-width':'.3'}));let t=el('text',{x:x+1,y:y0+5,fill:'#eee','font-size':4});t.textContent=x;canvas.append(t);}for(let y=Math.ceil(y0/10)*10;y<y1;y+=10){let t=el('text',{x:2,y:y,fill:'#eee','font-size':4});t.textContent=y;canvas.append(t);}for(let x of data.grid_columns)canvas.append(el('line',{x1:x,x2:x,y1:y0,y2:y1,stroke:'#ffd875','stroke-width':'.35','stroke-dasharray':'2 3'}));for(let y of data.grid_rows)canvas.append(el('line',{x1:0,x2:381,y1:y,y2:y,stroke:'#ffd875','stroke-width':'.35','stroke-dasharray':'2 3'}));}document.querySelector('#count').textContent='84 candidate leaflet outlines · 6 stem spans · 2 supports · 23 unresolved regions. Unannotated pixels remain unknown.';}
document.querySelectorAll('select,input').forEach(e=>e.addEventListener('change',render));render();</script></html>'''
(out/'index.html').write_text(page.replace('DATA',json.dumps(data)))
print(out/'index.html')
